import { safeRace } from './safe-race';
import type { AsyncFn } from './type';

export interface FetcherOptions {
  asyncFn: AsyncFn;
  priority: number;
}

export interface RaceSchedulerOptions {
  /** 被丢弃的 promise 处理策略：永不解决/抛出特定异常 */
  discardedPromiseAction?: 'never-settled' | 'throw-error';
}

function createDeferred() {
  let outerResolve: ((arg: unknown) => void) | null = null,
    outerReject: ((arg: unknown) => void) | null = null;

  const promise = new Promise((resolve, reject) => {
    outerResolve = resolve;
    outerReject = reject;
  });

  return [promise, outerResolve!, outerReject!] as const;
}

class PromiseDiscardedError extends Error {}

export function isPromiseDiscardedError(v: unknown): v is PromiseDiscardedError {
  return v instanceof PromiseDiscardedError;
}

export function raceScheduler<T extends { [key: string]: FetcherOptions }>(
  fetchers: T,
  { discardedPromiseAction = 'never-settled' }: RaceSchedulerOptions = {},
): { [K in keyof T]: T[K]['asyncFn'] } {
  let runningHighestPriorityFetcherOptions: (FetcherOptions & { name: string }) | null = null;

  return Object.fromEntries(
    Object.entries(fetchers).map(([fetcherName, currentFetcher]) => {
      const { asyncFn, priority } = currentFetcher;
      const safeAsyncFn = safeRace(asyncFn);

      async function runAsyncFn(...args: unknown[]) {
        const [promise, resolve, reject] = createDeferred();
        /** 将本次 promise 的响应丢弃 */
        const discardResponse = () => {
          if (discardedPromiseAction === 'throw-error') {
            reject(new PromiseDiscardedError('The Promise has been discarded'));
          }
        };

        if (
          !runningHighestPriorityFetcherOptions ||
          // 同一个 fetcher 下面
          fetcherName === runningHighestPriorityFetcherOptions.name ||
          // 不同 fetcher 并且优先级更高
          priority > runningHighestPriorityFetcherOptions.priority
        ) {
          const current = (runningHighestPriorityFetcherOptions = {
            ...currentFetcher,
            name: fetcherName,
          });

          /**
           * 仅对同名任务做出响应
           * Q: 为什么同名任务下 runAsyncFn 多次调用不会导致多次响应？
           * A: safeAsyncFn 已经 safeRace 过了，在同一个请求响应周期内，仅响应一次
           */
          safeAsyncFn(...args)
            .then(data => {
              if (current.name === runningHighestPriorityFetcherOptions?.name) {
                resolve(data);
              } else {
                discardResponse();
              }
            })

            .catch(error => {
              if (current.name === runningHighestPriorityFetcherOptions?.name) {
                reject(error);
              } else {
                discardResponse();
              }
            })

            .finally(() => {
              if (current.name === runningHighestPriorityFetcherOptions?.name) {
                runningHighestPriorityFetcherOptions = null;
              }
            });

          return promise;
        }

        discardResponse();

        return promise;
      }

      return [fetcherName, runAsyncFn];
    }),
  ) as { [K in keyof T]: T[K]['asyncFn'] };
}
